func _record_putSliceExternalLabel(buf []byte, x []external.Label, loc string, num int) (int, error) {
	i := len(buf)
	for k := len(x) - 1; k >= 0; k-- {
		w, err := x[k].EncodeKanon(buf[:i])
		if err != nil {
			return 0, err
		}
		i -= w
		i = wire.PutUvarint(buf, i, uint64(w))
	}
	i = wire.PutUvarint(buf, i, uint64(len(buf)-i))
	return len(buf) - i, nil
}

// _record_putSlicePart writes the encoding of x, a []Part, into the end of buf,
// which has room for it, and returns its length.
func _record_putSlicePart(buf []byte, x []Part) int {
	i := len(buf)
	for k := len(x) - 1; k >= 0; k-- {
		w, _ := x[k].encodeKanon(buf[:i])
		i -= w
		i = wire.PutUvarint(buf, i, uint64(w))
	}
	i = wire.PutUvarint(buf, i, uint64(len(buf)-i))
	return len(buf) - i
}

// _record_deselectRecordKind zeroes the member of the union of Record.Kind that
// the discriminator selects.
func _record_deselectRecordKind(m *Record) {
	switch m.Kind {
	case RecordKindText:
		m.Text = ""
	case RecordKindNumber:
		m.Number = 0
	}
}

// _record_readSlicePart appends the elements that data encodes, a []Part
// without its length, to *dst. data starts at offset off of slab, and the
// decode enters depth levels below the value at most. loc and num locate the
// field in errors.
func _record_readSlicePart(dst *[]Part, data []byte, slab string, off, depth int, loc string, num int) error {
	if depth < 0 {
		return wire.DepthError(loc, num, off)
	}
	x := *dst
	if x == nil && len(data) > 0 {
		x = make([]Part, 0, wire.CountValues(data))
	}
	for i := 0; i < len(data); {
		x = append(x, Part{})
		last := len(x) - 1
		l, n := wire.Uvarint(data[i:])
		if n <= 0 || uint64(len(data)-i-n) < l {
			return wire.ReadError(n, loc, num, off+i)
		}
		i += n
		if depth < 1 {
			return wire.DepthError("Part", 0, off+i)
		}
		if err := x[last].decodeKanon(data[i:i+int(l)], slab, off+i, depth-1); err != nil {
			return err
		}
		i += int(l)
	}
	*dst = x
	return nil
}

// _record_readSliceExternalLabel appends the elements that data encodes, a
// []external.Label without its length, to *dst. data starts at offset off of
// slab, and the decode enters depth levels below the value at most. loc and num
// locate the field in errors.
func _record_readSliceExternalLabel(dst *[]external.Label, data []byte, slab string, off, depth int, loc string, num int) error {
	if depth < 0 {
		return wire.DepthError(loc, num, off)
	}
	x := *dst
	if x == nil && len(data) > 0 {
		x = make([]external.Label, 0, wire.CountValues(data))
	}
	for i := 0; i < len(data); {
		x = append(x, external.Label{})
		last := len(x) - 1
		l, n := wire.Uvarint(data[i:])
		if n <= 0 || uint64(len(data)-i-n) < l {
			return wire.ReadError(n, loc, num, off+i)
		}
		i += n
		if depth < 1 {
			return wire.DepthError("external.Label", 0, off+i)
		}
		if err := x[last].DecodeKanon(data[i:i+int(l)], wire.Nested(slab, off+i, depth-1)); err != nil {
			return err
		}
		i += int(l)
	}
	*dst = x
	return nil
}

// _record_readMapStringString adds the entries that data encodes, a
// map[string]string without its length, to *dst. With collect set, it clears
// *dst first, and the entries reuse the memory of up to 16 of its values. data
// starts at offset off of slab, and the decode enters depth levels below the
// value at most. loc and num locate the field in errors.
func _record_readMapStringString(dst *map[string]string, data []byte, slab string, off, depth int, collect bool, loc string, num int) error {
	if depth < 0 {
		return wire.DepthError(loc, num, off)
	}
	x := *dst
	if collect {
		clear(x)
	}
	if x == nil && len(data) > 0 {
		x = make(map[string]string)
		*dst = x
	}
	var mk string
	var mv string
	for i := 0; i < len(data); {
		{
			l, n := wire.Uvarint(data[i:])
			if n <= 0 || uint64(len(data)-i-n) < l {
				return wire.ReadError(n, loc, num, off+i)
			}
			i += n
			mk = slab[off+i : off+i+int(l)]
			i += int(l)
		}
		{
			l, n := wire.Uvarint(data[i:])
			if n <= 0 || uint64(len(data)-i-n) < l {
				return wire.ReadError(n, loc, num, off+i)
			}
			i += n
			mv = slab[off+i : off+i+int(l)]
			i += int(l)
		}
		x[mk] = mv
	}
	return nil
}

// _record_clonePtrPart returns a pointer to a copy of the value that x, a
// *Part, points at, and nil for a nil x.
func _record_clonePtrPart(x *Part) *Part {
	if x == nil {
		return nil
	}
	return x.CloneKanon()
}

// _record_cloneSlicePart returns a copy of x, a []Part, and nil for a nil x.
func _record_cloneSlicePart(x []Part) []Part {
	if x == nil {
		return nil
	}
	c := make([]Part, len(x))
	for k := range x {
		x[k].cloneKanon(&c[k])
	}
	return c
}

// _record_cloneSliceExternalLabel returns a copy of x, a []external.Label, and
// nil for a nil x.
func _record_cloneSliceExternalLabel(x []external.Label) []external.Label {
	if x == nil {
		return nil
	}
	c := make([]external.Label, len(x))
	for k := range x {
		c[k] = *x[k].CloneKanon()
	}
	return c
}

// _record_cloneMapStringString returns a copy of x, a map[string]string, and
// nil for a nil x.
func _record_cloneMapStringString(x map[string]string) map[string]string {
	if x == nil {
		return nil
	}
	c := make(map[string]string, len(x))
	for mk, mv := range x {
		c[strings.Clone(mk)] = strings.Clone(mv)
	}
	return c
}
